SELECT ROUND((SUM(CASE WHEN substr("Order Date", 1, 4) = '2024' THEN "Total Revenue" ELSE 0 END) - SUM(CASE WHEN substr("Order Date", 1, 4) = '2023' THEN "Total Revenue" ELSE 0 END)) * 100.0 / NULLIF(SUM(CASE WHEN substr("Order Date", 1, 4) = '2023' THEN "Total Revenue" ELSE 0 END), 0), 2) AS "YoY Growth (%)"
FROM sales_data
WHERE "Region" = 'North America' AND substr("Order Date", 1, 4) IN ('2023', '2024');

